const assetCode = String(msg.payload || "").trim().toUpperCase();
if (!/^[A-Z0-9][A-Z0-9-]{1,49}$/.test(assetCode)) {
    node.error("Kode aset tidak valid."); return null;
}
flow.set("selected_asset_code", assetCode);
node.status({ fill: "blue", shape: "dot", text: "aset dipilih: " + assetCode });
msg.payload = { selected_asset_code: assetCode, note: "Klik tombol Normal/Peringatan/Kritis untuk mengirim pembacaan." };
return msg;

const assetCode = msg.payload?.asset_code || flow.get("selected_asset_code") || "BOX-02";
const mode = msg.payload?.mode;
if (!["NORMAL", "WARNING", "CRITICAL"].includes(mode)) {
    node.error("Skenario suhu tidak valid."); return null;
}
msg.scenario = { asset_code: assetCode, mode };
return msg;

const cached = flow.get("cached_assets");
const cacheTime = flow.get("cached_assets_time") || 0;
const now = Date.now();
const cacheTTL = 10 * 60 * 1000;
if (cached && (now - cacheTime) < cacheTTL) {
    msg.payload = { assets: cached };
    msg.fromCache = true;
    return [null, msg];
}
const token = env.get("ANTERAJA_INGEST_TOKEN");
if (!token) { node.error("Token API internal belum tersedia."); return null; }
msg.method = "GET";
msg.url = (env.get("ANTERAJA_API_BASE_URL") || "http://127.0.0.1:8090") + "/api/internal/thermal-assets";
msg.headers = { Authorization: "Bearer " + token, Accept: "application/json", Connection: "keep-alive" };
return [msg, null];

if (!msg.fromCache && msg.statusCode !== 200 || !Array.isArray(msg.payload?.assets)) {
    node.error("Daftar aset dari Laravel gagal dimuat."); return null;
}
const assets = msg.payload.assets;
if (!msg.fromCache) {
    flow.set("cached_assets", assets);
    flow.set("cached_assets_time", Date.now());
}
const selected = msg.scenario?.asset_code;
const mode = msg.scenario?.mode || "NORMAL";
const list = selected ? assets.filter(a => a.asset_code === selected) : assets;
if (!list.length) { node.error("Aset simulasi tidak ditemukan: " + selected); return null; }
const observedAt = new Date().toISOString();
const readings = list.map(asset => {
    const random = (Math.random() - 0.5) * 0.6;
    let value = asset.target_c + random;
    if (selected && mode === "WARNING") value = asset.normal_high_c + Math.min(0.3, (asset.warning_high_c - asset.normal_high_c) / 2);
    if (selected && mode === "CRITICAL") value = asset.warning_high_c + 1;
    return {
        message_id: asset.asset_code + ":" + Date.now().toString(36) + ":" + Math.random().toString(36).slice(2),
        asset_code: asset.asset_code,
        observed_at: observedAt,
        temperature_c: Number(value.toFixed(2))
    };
});
msg.payload = { readings };
msg.assetCount = readings.length;
return msg;

const token = env.get("ANTERAJA_INGEST_TOKEN");
if (!token) { node.error("Token API internal belum tersedia."); return null; }
msg.method = "POST";
msg.url = (env.get("ANTERAJA_API_BASE_URL") || "http://127.0.0.1:8090") + "/api/internal/temperature-readings";
msg.headers = { Authorization: "Bearer " + token, Accept: "application/json", "Content-Type": "application/json", Connection: "keep-alive" };
return msg;

if (![200, 201].includes(msg.statusCode)) {
    node.error("Laravel menolak pembacaan: HTTP " + msg.statusCode); return null;
}
node.status({ fill: "green", shape: "dot", text: (msg.payload?.inserted || 0) + " dari " + msg.assetCount + " aset tersimpan" });
msg.payload = { inserted: msg.payload.inserted, duplicates: msg.payload.duplicates, assets: msg.assetCount };
return msg;
